public int cycleInDirectedGraph(int A, int[][] B) {
    List<List<Integer>> adj = buildAdjacencyListForDirectedGraph(A, B);

    // nodes are 1-based, so size everything A + 1
    boolean[] visited = new boolean[A + 1];
    boolean[] recStack = new boolean[A + 1];

    for (int i = 1; i <= A; i++) {
        if (!visited[i]) {
            if (dfsForCycleDetection(i, adj, visited, recStack)) {
                return 1;
            }
        }
    }
    return 0;
}

private boolean dfsForCycleDetection(int node, List<List<Integer>> adj, boolean[] visited, boolean[] recStack) {
    visited[node] = true;
    recStack[node] = true;

    for (int neighbour : adj.get(node)) {
        if (!visited[neighbour]) {
            if (dfsForCycleDetection(neighbour, adj, visited, recStack)) {
                return true;
            }
        } else if (recStack[neighbour]) {
            return true; // back edge onto a node still on the current DFS path
        }
    }

    recStack[node] = false; // leaving the path, unmark
    return false;
}

private List<List<Integer>> buildAdjacencyListForDirectedGraph(int numberOfNodes, int[][] connections) {
    List<List<Integer>> adj = new ArrayList<>();

    for (int i = 0; i <= numberOfNodes; i++) {
        adj.add(new ArrayList<>());
    }

    for (int i = 0; i < connections.length; i++) {
        int u = connections[i][0]; // source
        int v = connections[i][1]; // dest
        adj.get(u).add(v);
    }
    return adj;
}

