private int dfsForPathInADirectedGraph(int node, int targetNode, List<List<Integer>> adj, boolean[] visited) {
    if (node == targetNode) {
        return 1;
    }
    visited[node] = true;

    for (int neighbour : adj.get(node)) {
        if (!visited[neighbour]) {
            // do not return directly, other neighbours still need a chance
            if (dfsForPathInADirectedGraph(neighbour, targetNode, adj, visited) == 1) {
                return 1;
            }
        }
    }
    return 0;
}

