public int firstDepthFirstSearch(int[] A, final int B, final int C) {
    List<List<Integer>> adj = buildAdjacencyListTownsProblem(A);
    boolean[] visited = new boolean[A.length + 1];

    // query is "is B reachable from C", so C is the source
    return dfsTownsProblem(C, adj, visited, B) ? 1 : 0;
}

private boolean dfsTownsProblem(int node, List<List<Integer>> adj, boolean[] visited, int destination) {
    if (node == destination) {
        return true;
    }
    visited[node] = true;

    for (int neighbour : adj.get(node)) {
        if (!visited[neighbour]) {
            if (dfsTownsProblem(neighbour, adj, visited, destination)) {
                return true;
            }
        }
    }
    return false;
}

private List<List<Integer>> buildAdjacencyListTownsProblem(int[] A) {
    List<List<Integer>> adj = new ArrayList<>();

    for (int i = 0; i <= A.length; i++) {
        adj.add(new ArrayList<>());
    }

    // A[0] is padding; edge A[i] -> i + 1, one direction only
    for (int i = 1; i < A.length; i++) {
        int u = A[i];
        int v = i + 1;
        adj.get(u).add(v);
    }
    return adj;
}

