private int maxLevel = 0;

public int[] maximumDepthQueries(int A, int[] B, int[] C, int[] D, int[] E, int[] F) {
    maxLevel = 0; // multiple test cases share the object, always reset
    Map<Integer, List<Integer>> adj = buildAdjacencyMapMaxDepth(A, B, C);
    boolean[] visited = new boolean[A + 1];
    Map<Integer, List<Integer>> levelList = new HashMap<>();

    dfsCollectLevels(1, adj, visited, 0, levelList);

    int[] result = new int[E.length];
    for (int i = 0; i < E.length; i++) {
        int res = Integer.MAX_VALUE;
        int level = E[i] % (maxLevel + 1);
        int threshold = F[i];

        for (int node : levelList.get(level)) {
            if (D[node - 1] >= threshold) { // node is 1-based, D is 0-based
                res = Math.min(res, D[node - 1]);
            }
        }
        result[i] = res != Integer.MAX_VALUE ? res : -1;
    }
    return result;
}

private void dfsCollectLevels(int node, Map<Integer, List<Integer>> adj, boolean[] visited, int level, Map<Integer, List<Integer>> levelList) {
    visited[node] = true;
    levelList.computeIfAbsent(level, k -> new ArrayList<>()).add(node);

    for (int neighbour : adj.get(node)) {
        if (!visited[neighbour]) {
            int newLev = level + 1;
            maxLevel = Math.max(maxLevel, newLev);
            dfsCollectLevels(neighbour, adj, visited, newLev, levelList);
        }
    }
}

private Map<Integer, List<Integer>> buildAdjacencyMapMaxDepth(int A, int[] B, int[] C) {
    Map<Integer, List<Integer>> adj = new HashMap<>();

    for (int i = 0; i < A - 1; i++) {
        int u = B[i];
        int v = C[i];
        adj.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        adj.computeIfAbsent(v, k -> new ArrayList<>()).add(u); // tree edges are undirected
    }
    return adj;
}

public int[] maximumDepthQueriesBinarySearch(int A, int[] B, int[] C, int[] D, int[] E, int[] F) {
    Map<Integer, List<Integer>> adj = buildAdjacencyMapMaxDepth(A, B, C);
    boolean[] visited = new boolean[A + 1];
    Map<Integer, List<Integer>> levelValues = new HashMap<>();

    dfsCollectValues(1, adj, visited, 0, D, levelValues);

    int maxLevel = 0;
    for (int level : levelValues.keySet()) {
        maxLevel = Math.max(maxLevel, level); // keySet order is not sorted, so scan it
    }

    for (List<Integer> values : levelValues.values()) {
        Collections.sort(values);
    }

    int[] result = new int[E.length];
    for (int i = 0; i < E.length; i++) {
        int level = E[i] % (maxLevel + 1);
        result[i] = smallestAtLeast(levelValues.get(level), F[i]);
    }
    return result;
}

private void dfsCollectValues(int node, Map<Integer, List<Integer>> adj, boolean[] visited, int level, int[] D, Map<Integer, List<Integer>> levelValues) {
    visited[node] = true;
    levelValues.computeIfAbsent(level, k -> new ArrayList<>()).add(D[node - 1]);

    for (int neighbour : adj.get(node)) {
        if (!visited[neighbour]) {
            dfsCollectValues(neighbour, adj, visited, level + 1, D, levelValues);
        }
    }
}

private int smallestAtLeast(List<Integer> sorted, int target) {
    int low = 0;
    int high = sorted.size() - 1;
    int ans = -1;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (sorted.get(mid) >= target) {
            ans = sorted.get(mid);
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

private Map<Integer, List<Integer>> buildAdjacencyMapMaxDepth(int A, int[] B, int[] C) {
    Map<Integer, List<Integer>> adj = new HashMap<>();

    for (int i = 0; i < A - 1; i++) {
        int u = B[i];
        int v = C[i];
        adj.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        adj.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }
    return adj;
}

public int commutableIslandsMinimumCost(int islands, int[][] bridges) {
    HashMap<Integer, ArrayList<Bridge>> adjacencyList = buildAdj(bridges);
    PriorityQueue<Bridge> minHeap = new PriorityQueue<>(Comparator.comparingInt(x -> x.cost));
    minHeap.add(new Bridge(1, 0));
    boolean[] visited = new boolean[islands + 1];
    int totalCost = 0;
    int islandVisitedSoFar = 0;

    while (!minHeap.isEmpty()) {
        Bridge current = minHeap.poll();
        int node = current.end;
        int cost = current.cost;
        if (visited[node]) {
            continue; // stale duplicate — a node can sit in the heap many times
        }
        visited[node] = true; // mark on POP, not on push
        islandVisitedSoFar++;
        totalCost += cost;
        for (Bridge neighbour : adjacencyList.getOrDefault(node, new ArrayList<>())) {
            if (!visited[neighbour.end]) {
                minHeap.add(new Bridge(neighbour.end, neighbour.cost)); // fresh object, raw edge weight
            }
        }
    }
    return islandVisitedSoFar == islands ? totalCost : -1;
}

private HashMap<Integer, ArrayList<Bridge>> buildAdj(int[][] bridges) {
    HashMap<Integer, ArrayList<Bridge>> map = new HashMap<>();
    for (int[] bridge : bridges) {
        int source = bridge[0];
        int dest = bridge[1];
        int cost = bridge[2];
        map.computeIfAbsent(source, k -> new ArrayList<>()).add(new Bridge(dest, cost));
        map.computeIfAbsent(dest, k -> new ArrayList<>()).add(new Bridge(source, cost));
    }
    return map;
}

private static class Bridge {
    int end, cost;

    Bridge(int end, int cost) {
        this.end = end;
        this.cost = cost;
    }
}

public int rottenOrangesMinimumMinutes(int[][] oranges) {
    int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    Queue<Position> queue = new LinkedList<>();
    int m = oranges.length;
    int n = oranges[0].length;
    int freshOranges = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (oranges[i][j] == 2) {
                queue.add(new Position(i, j));
            } else if (oranges[i][j] == 1) {
                freshOranges++;
            }
        }
    }

    int minutes = 0;
    if (freshOranges == 0) {
        return minutes;
    }

    while (!queue.isEmpty() && freshOranges > 0) {
        int currentLevelSize = queue.size(); // snapshot BEFORE popping — one level == one minute
        for (int i = 0; i < currentLevelSize; i++) {
            Position cell = queue.poll();
            for (int[] direction : directions) {
                int row = cell.row + direction[0];
                int col = cell.col + direction[1];
                if (isValidCell(row, col, m, n) && oranges[row][col] == 1) {
                    oranges[row][col] = 2; // mark rotten on ENQUEUE, else siblings re-enqueue it
                    freshOranges--;
                    queue.add(new Position(row, col));
                }
            }
        }
        minutes++;
    }
    return freshOranges == 0 ? minutes : -1;
}

private boolean isValidCell(int x, int y, int m, int n) {
    return x >= 0 && y >= 0 && x < m && y < n;
}

private static class Position {
    int row, col;

    Position(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

public int constructionCostMinimum(int A, int[][] B) {
    final int MOD = 1_000_000_007;
    if (A == 1) {
        return 0;
    }

    HashMap<Integer, ArrayList<Road>> map = buildAdj(B);
    PriorityQueue<Road> minHeap = new PriorityQueue<>(Comparator.comparingInt(x -> x.cost));
    minHeap.add(new Road(1, 0));
    boolean[] visited = new boolean[A + 1];
    long totalCost = 0;
    int centersToVisit = A;

    while (!minHeap.isEmpty() && centersToVisit > 0) {
        Road current = minHeap.poll();
        int node = current.node;
        int cost = current.cost;

        if (visited[node]) {
            continue;
        }

        visited[node] = true;
        totalCost = (totalCost + (long) cost) % MOD; // long accumulator — weights reach 10^9
        centersToVisit--;

        for (Road neighbour : map.getOrDefault(node, new ArrayList<>())) {
            if (!visited[neighbour.node]) {
                minHeap.add(new Road(neighbour.node, neighbour.cost));
            }
        }
    }

    return (int) totalCost;
}

private HashMap<Integer, ArrayList<Road>> buildAdj(int[][] B) {
    HashMap<Integer, ArrayList<Road>> map = new HashMap<>();
    for (int[] x : B) {
        int s = x[0];
        int d = x[1];
        int cost = x[2];
        map.computeIfAbsent(s, y -> new ArrayList<>()).add(new Road(d, cost));
        map.computeIfAbsent(d, y -> new ArrayList<>()).add(new Road(s, cost));
    }
    return map;
}

private static class Road {
    int node, cost;

    Road(int node, int cost) {
        this.node = node;
        this.cost = cost;
    }
}

