public void captureRegionsOnBoard(char[][] board) {
    int n = board.length;
    int m = board[0].length;
    Queue<int[]> queue = new LinkedList<>();

    for (int i = 0; i < n; i++) {
        seedIfOpen(board, queue, i, 0);
        seedIfOpen(board, queue, i, m - 1);
    }
    for (int j = 0; j < m; j++) {
        seedIfOpen(board, queue, 0, j);
        seedIfOpen(board, queue, n - 1, j);
    }

    int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    while (!queue.isEmpty()) {
        int[] cell = queue.poll();
        for (int[] direction : directions) {
            seedIfOpen(board, queue, cell[0] + direction[0], cell[1] + direction[1]);
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (board[i][j] == 'O') {
                board[i][j] = 'X';
            } else if (board[i][j] == '#') {
                board[i][j] = 'O';
            }
        }
    }
}

private void seedIfOpen(char[][] board, Queue<int[]> queue, int row, int col) {
    if (row < 0 || col < 0 || row >= board.length || col >= board[0].length) {
        return;
    }
    if (board[row][col] != 'O') {
        return;
    }
    board[row][col] = '#'; // mark BEFORE enqueue, else the same cell is queued repeatedly
    queue.add(new int[] {row, col});
}

public int blackShapesCount(String[] A) {
    int n = A.length;
    int m = A[0].length();
    boolean[][] visited = new boolean[n][m];
    int shapes = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (A[i].charAt(j) == 'X' && !visited[i][j]) {
                shapes++;
                floodFillShape(A, visited, i, j);
            }
        }
    }
    return shapes;
}

private void floodFillShape(String[] A, boolean[][] visited, int row, int col) {
    int n = A.length;
    int m = A[0].length();
    int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    Queue<int[]> queue = new LinkedList<>();
    visited[row][col] = true;
    queue.add(new int[] {row, col});

    while (!queue.isEmpty()) {
        int[] cell = queue.poll();
        for (int[] direction : directions) {
            int r = cell[0] + direction[0];
            int c = cell[1] + direction[1];
            if (r >= 0 && c >= 0 && r < n && c < m && !visited[r][c] && A[r].charAt(c) == 'X') {
                visited[r][c] = true; // mark on ENQUEUE, not on dequeue
                queue.add(new int[] {r, c});
            }
        }
    }
}

public int knightOnChessBoardMinimumMoves(int A, int B, int C, int D, int E, int F) {
    int[][] moves = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};
    boolean[][] visited = new boolean[A + 1][B + 1]; // 1-indexed board
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[] {C, D});
    visited[C][D] = true;
    int steps = 0;

    while (!queue.isEmpty()) {
        int levelSize = queue.size(); // one level == one knight move
        for (int i = 0; i < levelSize; i++) {
            int[] cell = queue.poll();
            if (cell[0] == E && cell[1] == F) {
                return steps; // checked on POP so source == destination returns 0
            }
            for (int[] move : moves) {
                int row = cell[0] + move[0];
                int col = cell[1] + move[1];
                if (isInsideBoard(row, col, A, B) && !visited[row][col]) {
                    visited[row][col] = true; // mark on ENQUEUE
                    queue.add(new int[] {row, col});
                }
            }
        }
        steps++;
    }
    return -1;
}

private boolean isInsideBoard(int row, int col, int A, int B) {
    return row >= 1 && col >= 1 && row <= A && col <= B;
}

public int damagedRoadsMinimumCost(int[] A, int[] B) {
    final int MOD = 1_000_000_007;
    int n = A.length;
    int m = B.length;
    Arrays.sort(A);
    Arrays.sort(B);

    long totalCost = 0;
    long rowGroups = n + 1; // row bands not yet stitched together
    long colGroups = m + 1; // column bands not yet stitched together
    int i = 0;
    int j = 0;

    while (i < n || j < m) {
        if (j == m || (i < n && A[i] <= B[j])) {
            totalCost = (totalCost + (long) A[i] * colGroups) % MOD; // multiplier from the OTHER axis
            rowGroups--;
            i++;
        } else {
            totalCost = (totalCost + (long) B[j] * rowGroups) % MOD;
            colGroups--;
            j++;
        }
    }

    return (int) totalCost;
}

