public int[] edgeInMinimumSpanningTree(int A, int[][] B) {
    int m = B.length;
    Integer[] order = new Integer[m];
    for (int i = 0; i < m; i++) {
        order[i] = i;
    }
    Arrays.sort(order, Comparator.comparingInt(i -> B[i][2]));

    int[] parent = new int[A + 1]; // nodes are 1..A
    int[] rank = new int[A + 1];
    for (int i = 0; i <= A; i++) {
        parent[i] = i;
    }

    int[] answer = new int[m];
    int start = 0;
    while (start < m) {
        int end = start;
        while (end < m && B[order[end]][2] == B[order[start]][2]) {
            end++;
        }

        for (int k = start; k < end; k++) {
            int[] edge = B[order[k]];
            if (find(parent, edge[0]) != find(parent, edge[1])) {
                answer[order[k]] = 1; // decide BEFORE any union inside this weight block
            }
        }

        for (int k = start; k < end; k++) {
            int[] edge = B[order[k]];
            union(parent, rank, edge[0], edge[1]);
        }

        start = end;
    }
    return answer;
}

private int find(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]]; // path halving
        x = parent[x];
    }
    return x;
}

private void union(int[] parent, int[] rank, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);
    if (rootX == rootY) {
        return;
    }
    if (rank[rootX] < rank[rootY]) {
        parent[rootX] = rootY;
    } else if (rank[rootX] > rank[rootY]) {
        parent[rootY] = rootX;
    } else {
        parent[rootY] = rootX;
        rank[rootX]++;
    }
}

public int courseScheduler(int A, int[] B, int[] C) {
    int[] dependencies = new int[A];
    boolean[] visited = new boolean[A];
    int visitedNodes = 0;
    HashMap<Integer, ArrayList<Integer>> map = new HashMap<>();

    for (int i = 0; i < B.length; i++) {
        int u = B[i];
        int v = C[i];
        map.computeIfAbsent(u, x -> new ArrayList<>()).add(v);
        dependencies[v - 1]++;
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int j = 1; j <= A; j++) {
        if (dependencies[j - 1] == 0) {
            queue.add(j);
        }
    }

    while (!queue.isEmpty()) {
        int node = queue.poll();
        if (visited[node - 1]) {
            continue;
        }
        visited[node - 1] = true;
        visitedNodes++;
        for (int neighbour : map.getOrDefault(node, new ArrayList<>())) {
            dependencies[neighbour - 1]--;
            if (dependencies[neighbour - 1] == 0) {
                queue.add(neighbour);
            }
        }
    }

    if (visitedNodes != A) {
        return 0;
    }
    return 1;
}

public int[] minimumDistanceForEachNodeUsingDijkstra(int A, int[][] B, int C) {
    HashMap<Integer, ArrayList<State>> adj = build(A, B);
    int[] distance = new int[A];
    boolean[] visited = new boolean[A];
    Arrays.fill(distance, -1);
    PriorityQueue<State> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a.weight));
    distance[C] = 0;
    minHeap.add(new State(C, 0));

    while (!minHeap.isEmpty()) {
        State current = minHeap.poll();
        int node = current.node;
        int dist = current.weight;
        if (visited[node]) {
            continue; // stale heavier copy left in the heap
        }
        visited[node] = true;

        for (State neighbour : adj.getOrDefault(node, new ArrayList<>())) {
            int child = neighbour.node;
            if (visited[child]) {
                continue;
            }
            int weight = neighbour.weight;
            if (distance[child] == -1 || dist + weight < distance[child]) {
                distance[child] = dist + weight;
                minHeap.add(new State(child, dist + weight));
            }
        }
    }

    return distance;
}

private HashMap<Integer, ArrayList<State>> build(int A, int[][] B) {
    HashMap<Integer, ArrayList<State>> map = new HashMap<>();
    for (int[] s : B) {
        int u = s[0];
        int v = s[1];
        int w = s[2];
        map.computeIfAbsent(u, x -> new ArrayList<>()).add(new State(v, w));
        map.computeIfAbsent(v, x -> new ArrayList<>()).add(new State(u, w));
    }
    return map;
}

private class State {
    int node;
    int weight;

    State(int n, int w) {
        this.node = n;
        this.weight = w;
    }
}

public int anotherBfsShortestPath(int A, int[][] B, int C, int D) {
    int total = A + B.length;
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < total; i++) {
        graph.add(new ArrayList<>());
    }

    int next = A;
    for (int[] edge : B) {
        int u = edge[0];
        int v = edge[1];
        if (edge[2] == 1) {
            graph.get(u).add(v);
            graph.get(v).add(u);
        } else {
            int mid = next++; // split the weight-2 edge into two unit edges
            graph.get(u).add(mid);
            graph.get(mid).add(u);
            graph.get(mid).add(v);
            graph.get(v).add(mid);
        }
    }

    int[] dist = new int[total];
    Arrays.fill(dist, -1);
    dist[C] = 0;
    Queue<Integer> queue = new LinkedList<>();
    queue.add(C);

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbour : graph.get(node)) {
            if (dist[neighbour] == -1) {
                dist[neighbour] = dist[node] + 1;
                queue.add(neighbour);
            }
        }
    }

    return dist[D];
}

public int shortestPath(int A, int[][] B, int C, int D) {
    List<List<Node>> graph = new ArrayList<>();
    for (int i = 0; i < A; i++) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : B) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        graph.get(u).add(new Node(v, w));
        graph.get(v).add(new Node(u, w));
    }

    int[] dist = new int[A];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[C] = 0;

    PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingInt(node -> node.weight));
    pq.offer(new Node(C, 0));

    while (!pq.isEmpty()) {
        Node node = pq.poll();
        int u = node.id;

        if (u == D) {
            break;
        }
        if (node.weight > dist[u]) {
            continue; // stale entry, already finalised cheaper
        }

        for (Node neighbor : graph.get(u)) {
            int v = neighbor.id;
            int weight = neighbor.weight;
            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                pq.offer(new Node(v, dist[v]));
            }
        }
    }

    return dist[D] == Integer.MAX_VALUE ? -1 : dist[D];
}

private class Node {
    int id;
    int weight;

    Node(int id, int weight) {
        this.id = id;
        this.weight = weight;
    }
}

