public int largestDistanceBetweenNodes(int[] A) {
    int n = A.length;
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }

    for (int i = 0; i < n; i++) {
        if (A[i] != -1) {
            tree.get(i).add(A[i]);
            tree.get(A[i]).add(i); // undirected - the diameter need not pass the root
        }
    }

    int[] first = bfsFarthest(tree, 0, n);
    int[] second = bfsFarthest(tree, first[0], n);
    return second[1];
}

private int[] bfsFarthest(List<List<Integer>> tree, int src, int n) {
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    dist[src] = 0;
    Queue<Integer> queue = new LinkedList<>();
    queue.add(src);
    int far = src;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        if (dist[node] > dist[far]) {
            far = node;
        }
        for (int neighbour : tree.get(node)) {
            if (dist[neighbour] == -1) {
                dist[neighbour] = dist[node] + 1;
                queue.add(neighbour);
            }
        }
    }

    return new int[] { far, dist[far] };
}

