public int shortestDistanceInAMaze(int[][] A, int[] B, int[] C) {
    int n = A.length, m = A[0].length;
    int[][] dist = new int[n][m];
    for (int[] row : dist) {
        Arrays.fill(row, Integer.MAX_VALUE);
    }
    dist[B[0]][B[1]] = 0;

    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{B[0], B[1]});

    int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    while (!queue.isEmpty()) {
        int[] cur = queue.poll();
        for (int[] d : dirs) {
            int x = cur[0], y = cur[1], count = 0;
            while (isValid(n, m, x + d[0], y + d[1]) && A[x + d[0]][y + d[1]] == 0) {
                x += d[0];
                y += d[1];
                count++;
            }
            // strict improvement only, else a blocked direction re-pushes cur forever
            if (dist[cur[0]][cur[1]] + count < dist[x][y]) {
                dist[x][y] = dist[cur[0]][cur[1]] + count;
                queue.add(new int[]{x, y});
            }
        }
    }

    return dist[C[0]][C[1]] == Integer.MAX_VALUE ? -1 : dist[C[0]][C[1]];
}

